// Generates the short word descriptions shown when a finished category is
// opened, one raw batch file at a time.
//
//   node scripts/generate-descriptions.mjs batch01
//   node scripts/generate-descriptions.mjs batch01 --dry-run
//
// Output goes to scripts/data/descriptions/<batch>.mjs, which is committed and
// meant to be read and corrected by hand. The generator never overwrites an
// existing entry — it only fills in words that have no description yet — so a
// manual fix survives a re-run, and a bad description is re-generated by
// deleting its line and running the script again.
//
// One request per category: 40 words is a comfortable amount of context for the
// model, and it can see the whole category at once, which is what lets it pick
// the trait that distinguishes each word from its neighbours.

import { mkdir } from "node:fs/promises";
import { writeFileSync } from "node:fs";
import path from "node:path";
import Anthropic from "@anthropic-ai/sdk";
import {
  MAX_DESCRIPTION_LENGTH,
  dataDir,
  descriptionsDir,
  loadDescriptions,
  loadShippedCategories,
  norm,
  validateDescription,
} from "./categories.mjs";

const MODEL = "claude-opus-5";
/** Requests in flight at once. Low enough to stay well inside any rate limit. */
const CONCURRENCY = 3;

const args = process.argv.slice(2);
const dryRun = args.includes("--dry-run");
const batch = args.find((a) => !a.startsWith("--"));

if (!batch) {
  console.error("Bruk: node scripts/generate-descriptions.mjs <batch> [--dry-run]");
  console.error("F.eks. node scripts/generate-descriptions.mjs batch01");
  process.exit(1);
}

const batchFile = `${batch.replace(/\.mjs$/, "")}.mjs`;
const outFile = path.join(descriptionsDir, batchFile);

// --- Work out what needs describing -----------------------------------------

/** The category names this raw batch file owns. */
const batchModule = await import(path.join(dataDir, batchFile)).catch(() => null);
if (!batchModule) {
  console.error(`Fant ikke scripts/data/${batchFile}`);
  process.exit(1);
}
const batchNames = new Set(Object.keys(batchModule.default));

// Resolve against the shipped list rather than the raw file: excluded
// categories, deduped words and the 40-word trim all apply first, so we never
// pay for a description that the build would discard.
const { shipped } = await loadShippedCategories();
const { descriptions: existing } = await loadDescriptions();

const todo = shipped
  .filter((c) => batchNames.has(c.name))
  .map((c) => ({ name: c.name, words: c.words.filter((w) => !existing.has(norm(w))) }))
  .filter((c) => c.words.length > 0);

if (todo.length === 0) {
  console.log(`Ingenting å gjøre — alle ord i ${batchFile} har allerede beskrivelser.`);
  process.exit(0);
}

const wordCount = todo.reduce((n, c) => n + c.words.length, 0);
console.log(`${batchFile}: ${todo.length} kategori(er), ${wordCount} ord uten beskrivelse.`);
if (dryRun) {
  for (const c of todo) console.log(`   - ${c.name}: ${c.words.length} ord`);
  process.exit(0);
}

// --- The prompt -------------------------------------------------------------

const SYSTEM = `Du skriver korte ordforklaringer til et norsk ordspill. Spilleren har
nettopp løst en kategori og trykker på den for å se hva hvert ord faktisk betyr.

Regler for hver beskrivelse:
- Norsk bokmål, én setning, maks ${MAX_DESCRIPTION_LENGTH} tegn inkludert mellomrom. Dette er en hard grense.
- Si det som skiller nettopp dette ordet fra de andre i kategorien. Ikke gjenta
  kategorinavnet — spilleren ser det rett over.
- Begynn ikke med ordet selv, og ikke med "En", "Et" eller "Den".
- Vær konkret: et tall, et sted, en funksjon, et årstall. Ikke "kjent for å være
  populær" eller annet innholdsløst fyll.
- Skriv bare det du er trygg på. Er du usikker på en detalj, ta med det generelle
  i stedet for å gjette på det spesifikke. En vag beskrivelse er grei; en feil er det ikke.

Eksempler på riktig form:
  hydrogen -> "Letteste grunnstoffet, nummer 1, symbol H."
  Portugal -> "Ligger vest for Spania, med Lisboa som hovedstad."
  Python -> "Lansert i 1991, kjent for lesbar syntaks og innrykk som struktur."`;

const SCHEMA = {
  type: "object",
  properties: {
    beskrivelser: {
      type: "array",
      items: {
        type: "object",
        properties: {
          ord: { type: "string" },
          beskrivelse: { type: "string" },
        },
        required: ["ord", "beskrivelse"],
        additionalProperties: false,
      },
    },
  },
  required: ["beskrivelser"],
  additionalProperties: false,
};

const client = new Anthropic();
const usage = { input: 0, output: 0 };

async function ask(messages) {
  const response = await client.messages.create({
    model: MODEL,
    max_tokens: 16000,
    system: SYSTEM,
    output_config: {
      // `high` is the API default, spelled out because it is the one knob worth
      // turning: the task is factual recall, not agentic work, so `xhigh` buys
      // nothing. Try `medium` once the output quality is known — it is where
      // the cost actually drops.
      effort: "high",
      // Structured outputs, so the response is guaranteed to parse. Length is NOT
      // expressible in the schema (JSON Schema string constraints are unsupported),
      // which is why the caller still validates and asks for a repair pass.
      format: { type: "json_schema", schema: SCHEMA },
    },
    messages,
  });
  usage.input += response.usage.input_tokens;
  usage.output += response.usage.output_tokens;

  const text = response.content.find((b) => b.type === "text")?.text ?? "";
  return JSON.parse(text).beskrivelser;
}

/** Descriptions for one category, with a single repair pass for bad entries. */
async function describe(category) {
  const list = category.words.map((w) => `- ${w}`).join("\n");
  const messages = [
    {
      role: "user",
      content: `Kategori: ${category.name}\n\nSkriv én beskrivelse for hvert av disse ordene:\n\n${list}`,
    },
  ];

  let entries = await ask(messages);
  let result = new Map(entries.map((e) => [norm(e.ord), e.beskrivelse.trim()]));

  const bad = category.words.filter((w) => {
    const text = result.get(norm(w));
    return text === undefined || validateDescription(w, text).length > 0;
  });

  if (bad.length > 0) {
    const notes = bad
      .map((w) => {
        const text = result.get(norm(w));
        if (text === undefined) return `- ${w}: mangler helt`;
        return `- ${w}: ${text.length} tegn — «${text}»`;
      })
      .join("\n");
    messages.push({ role: "assistant", content: JSON.stringify({ beskrivelser: entries }) });
    messages.push({
      role: "user",
      content: `Disse holder ikke målet:\n\n${notes}\n\nSkriv dem om. Maks ${MAX_DESCRIPTION_LENGTH} tegn hver. Returner bare disse ordene.`,
    });
    for (const e of await ask(messages)) {
      if (bad.some((w) => norm(w) === norm(e.ord))) result.set(norm(e.ord), e.beskrivelse.trim());
    }
  }

  return result;
}

// --- Run --------------------------------------------------------------------

/** word (original spelling) -> description, in the order the categories list them. */
const generated = new Map();
const failures = [];

const queue = [...todo];
await Promise.all(
  Array.from({ length: Math.min(CONCURRENCY, queue.length) }, async () => {
    for (let category = queue.shift(); category; category = queue.shift()) {
      try {
        const result = await describe(category);
        let kept = 0;
        for (const word of category.words) {
          const text = result.get(norm(word));
          const problems = text === undefined ? [`"${word}": mangler`] : validateDescription(word, text);
          if (problems.length > 0) {
            failures.push(...problems);
            continue;
          }
          generated.set(word, text);
          kept++;
        }
        console.log(`✅ ${category.name}: ${kept}/${category.words.length}`);
      } catch (error) {
        failures.push(`"${category.name}": ${error}`);
        console.error(`❌ ${category.name}: ${error}`);
      }
    }
  }),
);

if (generated.size === 0) {
  console.error("\nIngen brukbare beskrivelser. Skriver ingenting.");
  process.exit(1);
}

// --- Write ------------------------------------------------------------------

// Merge rather than replace: entries already in this file were either reviewed
// by a human or generated in an earlier run, and both outrank a fresh guess.
const previous = await import(outFile).then((m) => m.default).catch(() => ({}));
const merged = { ...previous };
for (const [word, text] of generated) if (!(norm(word) in merged)) merged[word] = text;

const body = Object.entries(merged)
  .map(([word, text]) => `  ${JSON.stringify(word)}: ${JSON.stringify(text)},`)
  .join("\n");

await mkdir(descriptionsDir, { recursive: true });
writeFileSync(
  outFile,
  `// Generert av scripts/generate-descriptions.mjs — les gjennom og rett fritt.
// Generatoren rører aldri en linje som allerede står her; slett en linje for å
// få den skrevet på nytt.
export default {
${body}
};
`,
);

const cost = (usage.input / 1e6) * 5 + (usage.output / 1e6) * 25;
console.log(`\n✅ Skrev ${generated.size} nye beskrivelser til ${outFile}`);
console.log(
  `   ${usage.input} inn-tokens, ${usage.output} ut-tokens — ca. $${cost.toFixed(2)} (${MODEL})`,
);
if (failures.length > 0) {
  console.log(`\n⚠️  ${failures.length} ord uten brukbar beskrivelse:`);
  console.log(failures.slice(0, 20).join("\n"));
  console.log("Kjør skriptet på nytt for å prøve disse igjen.");
}
